"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10432"],{91613(e){e.exports=JSON.parse('{"id":"FIN-200","slug":"headcount-forecast","term":"Headcount Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"A headcount forecast is a plan of how many employees a business expects to have over a future period, by team or role, and what they will cost.","explanation":["Staff are often a company\'s largest expense, especially in service and technology businesses. A headcount forecast shows how many people will be employed each month, when new hires will start and what salaries, benefits and taxes will add up to.","The forecast usually starts with current staff, then adds planned hires and expected departures. Each role is assigned a start date and an annual cost, including salary, employer taxes, benefits and other related costs such as equipment.","For example, a company planning to hire five engineers in March at a total annual cost of 90,000 each would add about 37,500 a month to staff costs from March onwards.","Headcount forecasts link directly to revenue plans, because more sales often require more staff, and to cash flow forecasts, because wages must be paid every month. They also help managers plan recruitment, office space and training. Because hiring often takes longer than expected, comparing planned with actual headcount is a regular part of financial reviews."],"note":"","total":1500,"prev":{"slug":"harmonic-mean","term":"Harmonic Mean"},"next":{"slug":"health-insurance","term":"Health Insurance"}}')}}]);